css:
table {
    margin: 0 auto; /* or margin: 0 auto 0 auto */
    width: 90%;
    line-height: 1;
  }
#table2 {
   font-family: Arial, Helvetica, sans-serif;
   border-collapse: collapse;
   width: 100%;
    background-color: #04aa6d;
    
}

#table2 td, #table2 th {
  border: 1px solid #bfbdbd;
  padding: 2px;
  padding-top: 2px;
  padding-bottom: 2px;
}

#table2 tr:nth-child(even){background-color: #f2f2f2;}

#table2 tr:hover {background-color: #ddd;}

#table2 th {
  padding-top: 2px;
  padding-bottom: 2px;
  text-align: left;
  background-color: #04aa6d;
  color: white;
}

#main {
   margin-left: 20px;
   margin-right: 20px;
}
@media all {
   div .printedby {
       position: fixed;
       bottom: 0;
       text-align: center;
       font-size: xx-small;
       width: 100% !important;
   }
}
